BEGIN;
CREATE TABLE automation_connections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),kind text NOT NULL CHECK(kind IN('crm','webhook','whatsapp','sms','payment_link','appointment','otp','survey','collections')),name text NOT NULL,endpoint_url text NOT NULL,secret_ref text NOT NULL,status text NOT NULL DEFAULT 'disabled' CHECK(status IN('disabled','testing','active','degraded','revoked')),event_types text[] NOT NULL DEFAULT '{}',configuration jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,kind,name));
CREATE TABLE automation_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),connection_id uuid NOT NULL REFERENCES automation_connections(id),event_type text NOT NULL,idempotency_key text NOT NULL,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','processing','delivered','failed','cancelled')),attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),lease_owner text,lease_until timestamptz,last_error text,response_code integer,delivered_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,idempotency_key));
CREATE INDEX automation_jobs_delivery_idx ON automation_jobs(tenant_id,state,available_at,created_at) WHERE state IN('queued','processing');
ALTER TABLE automation_connections ENABLE ROW LEVEL SECURITY;ALTER TABLE automation_connections FORCE ROW LEVEL SECURITY;ALTER TABLE automation_jobs ENABLE ROW LEVEL SECURITY;ALTER TABLE automation_jobs FORCE ROW LEVEL SECURITY;
CREATE POLICY automation_connections_isolation ON automation_connections USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY automation_jobs_isolation ON automation_jobs USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
COMMIT;
